insert into items (id, nivel, tipo, grupo, orden_grupo, instruccion_ja, enunciado, objetivo, opciones, respuesta, logica_distractores, explicacion, puntos, pasaje, guion, audio, etiquetas, dificultad) values
  ('n1-bunpou1-0001', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '事故の原因については、調査の結果を待つ（　）。', null, '["ほかない", "ものがある", "きらいがある", "にすぎない"]'::jsonb, 0, '["ものがあるは感嘆", "きらいがあるは傾向", "にすぎないは限定"]'::jsonb, '{"es": "〜ほかない = no queda más remedio. Es la única opción disponible.", "en": "〜ほかない = there''s nothing for it but. It''s the only option left."}'::jsonb, null, null, null, null, '["限定"]'::jsonb, 4),
  ('n1-bunpou1-0002', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '社長（　）者が、社員の前でそんな発言をするべきではない。', null, '["たる", "なる", "めく", "がち"]'::jsonb, 0, '["なるは連体", "めくは様子", "がちは傾向"]'::jsonb, '{"es": "〜たる者 = «quien es …, en su condición de». Marca la responsabilidad del cargo.", "en": "〜たる者 = ''one who is …, in that capacity''. It marks the duty of the role."}'::jsonb, null, null, null, null, '["立場"]'::jsonb, 5),
  ('n1-bunpou1-0003', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '雨天（　）、大会は予定どおり行われます。', null, '["といえども", "にもまして", "をおいて", "ならでは"]'::jsonb, 0, '["にもましては比較", "をおいてはただ一つ", "ならではは固有性"]'::jsonb, '{"es": "〜といえども = «aun siendo…, aunque sea…». Concesivo formal.", "en": "〜といえども = ''even if it is…''. A formal concessive."}'::jsonb, null, null, null, null, '["逆接"]'::jsonb, 5),
  ('n1-bunpou1-0004', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '皆様のご協力（　）、この計画は実現しませんでした。', null, '["なくしては", "をもって", "にかけては", "ながらに"]'::jsonb, 0, '["をもっては手段", "にかけてはは得意分野", "ながらには継続"]'::jsonb, '{"es": "〜なくしては = «sin …, no». Marca condición indispensable.", "en": "〜なくしては = ''without …, not''. It marks an indispensable condition."}'::jsonb, null, null, null, null, '["条件"]'::jsonb, 5),
  ('n1-bunpou1-0005', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この問題の難しさは、経験した者（　）分からないだろう。', null, '["でなければ", "であれば", "にしては", "とあって"]'::jsonb, 0, '["肯定条件では意味が逆", "にしてはは予想との差", "とあっては理由"]'::jsonb, '{"es": "者でなければ分からない = solo quien lo ha vivido lo entiende. La negativa es la que da el sentido.", "en": "者でなければ分からない = only someone who has lived it understands. The negative carries the meaning."}'::jsonb, null, null, null, null, '["限定"]'::jsonb, 4),
  ('n1-bunpou1-0006', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は忙しさ（　）、返事を出すのを忘れていたらしい。', null, '["にかまけて", "にひきかえ", "をよそに", "にもまして"]'::jsonb, 0, '["にひきかえは対比", "をよそには無視", "にもましては比較"]'::jsonb, '{"es": "〜にかまけて = estar tan absorbido por algo que se descuida lo demás.", "en": "〜にかまけて = to be so taken up with something that everything else is neglected."}'::jsonb, null, null, null, null, '["原因"]'::jsonb, 5),
  ('n1-bunpou2-0001', 'N1', 'bunpou2', null, 0, '次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。', '今回の結果は　＿＿　＿★＿　＿＿　＿＿　ものだ。', null, '["努力の", "たまものと", "日ごろの", "言うべき"]'::jsonb, 0, '["語順が合わない", "語順が合わない", "語順が合わない"]'::jsonb, '{"es": "Orden: 日ごろの 努力の たまものと 言うべき. La estrella está en la casilla 2, donde va 「努力の」.", "en": "Order: 日ごろの 努力の たまものと 言うべき. The star is in slot 2, which takes 「努力の」."}'::jsonb, null, null, null, null, '["並べ替え"]'::jsonb, 5),
  ('n1-bunpou2-0002', 'N1', 'bunpou2', null, 0, '次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。', 'この装置は　＿＿　＿＿　＿★＿　＿＿　設計されている。', null, '["使えるように", "子どもでも", "安全に", "操作を誤っても"]'::jsonb, 2, '["語順が合わない", "語順が合わない", "語順が合わない"]'::jsonb, '{"es": "Orden: 子どもでも 操作を誤っても 安全に 使えるように. La estrella está en la casilla 3, donde va 「安全に」.", "en": "Order: 子どもでも 操作を誤っても 安全に 使えるように. The star is in slot 3, which takes 「安全に」."}'::jsonb, null, null, null, null, '["並べ替え"]'::jsonb, 5),
  ('n1-bunpou1-0007', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この結果は、長年の地道な努力（　）ものだ。', null, '["あっての", "ならではの", "ながらの", "かぎりの"]'::jsonb, 0, '["ならではは固有性", "ながらは継続", "かぎりは限定"]'::jsonb, '{"es": "〜あっての = «que solo existe gracias a». Sin ese esfuerzo no habría resultado.", "en": "〜あっての = ''which exists only thanks to''. Without that effort there''d be no result."}'::jsonb, null, null, null, null, '["前提"]'::jsonb, 5),
  ('n1-bunpou1-0008', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '周囲の反対（　）、彼は計画を進めた。', null, '["をよそに", "にそくして", "にかかわって", "をこめて"]'::jsonb, 0, '["にそくしては基づく", "にかかわっては関与", "をこめては感情"]'::jsonb, '{"es": "〜をよそに = haciendo caso omiso de. Sigue adelante pese a la oposición.", "en": "〜をよそに = disregarding. He pressed on despite the opposition."}'::jsonb, null, null, null, null, '["無視"]'::jsonb, 5),
  ('n1-bunpou1-0009', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '締め切りが明日（　）、今から間に合わせるのは難しい。', null, '["とあっては", "とばかりに", "といっては", "ときたら"]'::jsonb, 0, '["とばかりには様子", "といってはは引用", "ときたらは話題提示"]'::jsonb, '{"es": "〜とあっては = «siendo el caso que…, entonces». Introduce una consecuencia forzosa.", "en": "〜とあっては = ''given that…, then''. It introduces an unavoidable consequence."}'::jsonb, null, null, null, null, '["条件"]'::jsonb, 5),
  ('n1-bunpou1-0010', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼の実力なら、優勝も（　）。', null, '["夢ではあるまい", "夢ではあるまいし", "夢どころではない", "夢にすぎない"]'::jsonb, 0, '["ではあるまいしは理由の否定", "どころではないは余裕がない", "にすぎないは限定"]'::jsonb, '{"es": "〜まい niega con conjetura: «no será un sueño», o sea, es alcanzable.", "en": "〜まい negates with conjecture: ''it likely isn''t a dream'', i.e. it''s within reach."}'::jsonb, null, null, null, null, '["推量"]'::jsonb, 5),
  ('n1-bunpou2-0003', 'N1', 'bunpou2', null, 0, '次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。', 'その決断は　＿＿　＿★＿　＿＿　＿＿　ではない。', null, '["容易に", "下せるもの", "立場でなければ", "責任ある"]'::jsonb, 2, '["語順が合わない", "語順が合わない", "語順が合わない"]'::jsonb, '{"es": "Orden: 責任ある 立場でなければ 容易に 下せるもの. La estrella está en la casilla 2, donde va 「立場でなければ」.", "en": "Order: 責任ある 立場でなければ 容易に 下せるもの. The star is in slot 2, which takes 「立場でなければ」."}'::jsonb, null, null, null, null, '["並べ替え"]'::jsonb, 5),
  ('n1-bunpou2-0004', 'N1', 'bunpou2', null, 0, '次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。', '制度の見直しは　＿＿　＿＿　＿★＿　＿＿　進められた。', null, '["現場の声を", "反対を", "踏まえつつ", "押し切る形で"]'::jsonb, 1, '["語順が合わない", "語順が合わない", "語順が合わない"]'::jsonb, '{"es": "Orden: 現場の声を 踏まえつつ 反対を 押し切る形で. La estrella está en la casilla 3, donde va 「反対を」.", "en": "Order: 現場の声を 踏まえつつ 反対を 押し切る形で. The star is in slot 3, which takes 「反対を」."}'::jsonb, null, null, null, null, '["並べ替え"]'::jsonb, 5),
  ('n1-bunshou_bunpou-0001', 'N1', 'bunshou_bunpou', 'n1-bb-g001', 0, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　1　）', null, '["わかりやすさはかえって妨げになりうる", "わかりやすさこそが唯一の方法である", "聞き手の枠組みは問題にならない", "話し手の負担は軽くなる"]'::jsonb, 0, '["本文の論旨と逆", "枠組みが問題だと述べている", "負担の話は次の段落"]'::jsonb, '{"es": "Si hay que cambiar el marco del oyente, encajar la información en ese mismo marco estorba.", "en": "If the listener''s framework itself must change, fitting information into that framework gets in the way."}'::jsonb, null, '{"texto": "「わかりやすく話してください」と頼まれることがある。ありがたい要望だが、応じるのは思うほど簡単ではない。わかりやすさとは、聞き手がすでに持っている枠組みに情報を収めることだからだ。枠組みそのものを変えてもらう必要がある場合、（　1　）。\nそれでも、話し手にできることはある。結論を先に置くこと、例を一つに絞ること、専門語を言い換えること。これらはいずれも、聞き手の負担を減らす工夫である。（　2　）、内容そのものを薄めることとは違う。\n難しい話をやさしく話すのと、やさしい話に置き換えてしまうのとは別である。前者は聞き手への敬意だが、後者は（　3　）。両者の境目を見失わないことが、話し手の責任なのだと思う。", "notas": [{"termino": "枠組み", "glosa": "ものごとを理解するときの下地となる考え方"}]}'::jsonb, null, null, '["文章の文法"]'::jsonb, 5),
  ('n1-bunshou_bunpou-0002', 'N1', 'bunshou_bunpou', 'n1-bb-g001', 1, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　2　）', null, '["ただし", "つまり", "したがって", "たとえば"]'::jsonb, 0, '["言い換えではない", "帰結ではない", "例示ではない"]'::jsonb, '{"es": "Va a poner un límite a lo dicho: reducir la carga sí, diluir el contenido no. ただし.", "en": "He''s about to qualify what he said: lighten the load yes, dilute the content no. ただし."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 4),
  ('n1-bunshou_bunpou-0003', 'N1', 'bunshou_bunpou', 'n1-bb-g001', 2, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　3　）', null, '["聞き手を見くびることになりかねない", "聞き手への配慮そのものである", "話し手の実力を示している", "内容を深めることにつながる"]'::jsonb, 0, '["前者の説明", "本文にない", "本文と逆"]'::jsonb, '{"es": "El primero es respeto; el segundo, sustituir el tema por otro más fácil, subestima al oyente.", "en": "The first is respect; the second — swapping the topic for an easier one — sells the listener short."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 5),
  ('n1-kadai-0001', 'N1', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '女の人はこの後まず何をしますか。', null, '["見積もりを取り直す", "仕様書を修正する", "部長に報告する", "業者に連絡する"]'::jsonb, 1, '["見積もりは仕様が固まってから", "報告は数字が出てから", "連絡は修正の後"]'::jsonb, '{"es": "El presupuesto no se puede rehacer hasta que el pliego refleje el cambio, así que lo primero es corregirlo.", "en": "The quote can''t be redone until the spec reflects the change, so correcting it comes first."}'::jsonb, '["仕様が変わった → 仕様書の修正が先", "見積もりは仕様書を送ってから", "報告は数字が出そろってから"]'::jsonb, null, '{"intro": "会社で男の人と女の人が話しています。女の人はこの後まず何をしますか。", "turnos": [{"quien": "M", "texto": "例の件、先方から仕様の変更が入ったそうですね。"}, {"quien": "F", "texto": "ええ。見積もりを取り直さないといけません。"}, {"quien": "M", "texto": "でも、仕様書がまだ前のままでは、業者も出しようがないでしょう。"}, {"quien": "F", "texto": "あ、たしかに。先に直しておかないと。"}, {"quien": "M", "texto": "それができたら業者に送って、数字が出てから部長に報告しましょう。"}], "pregunta": "女の人はこの後まず何をしますか。"}'::jsonb, null, '["課題理解"]'::jsonb, 5),
  ('n1-point-0001', 'N1', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人が今回の企画で最も重視したのは何ですか。', null, '["費用を抑えること", "参加者が意見を言いやすいこと", "参加者を増やすこと", "時間を短くすること"]'::jsonb, 1, '["費用は結果として下がっただけ", "人数は増やさないと言っている", "時間はむしろ長くなった"]'::jsonb, '{"es": "Dice que lo primero fue que la gente pudiera hablar; por eso redujo el aforo aunque alargara la sesión.", "en": "He says the priority was that people could speak; that''s why he cut attendance even though it lengthened the session."}'::jsonb, '["人数は絞った → 増やしていない", "時間は長くなった → 短縮ではない", "発言しやすさを最優先"]'::jsonb, null, '{"intro": "男の人が企画について話しています。男の人が今回の企画で最も重視したのは何ですか。", "turnos": [{"quien": "M", "texto": "今回は思い切って参加者を二十名に絞りました。人数を増やせば会は大きく見えますが、それでは黙る人が出ます。時間も予定より三十分長くなりましたが、最後まで全員が一度は発言していました。費用は結果的に下がりましたけれど、そこは狙いではありません。"}], "pregunta": "男の人が今回の企画で最も重視したのは何ですか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 5),
  ('n1-gaiyou-0001', 'N1', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', 'この人は何について話していますか。', null, '["失敗の記録を残すことの意味", "会議の進め方", "新人の教育方法", "記録係の選び方"]'::jsonb, 0, '["会議は例として出ただけ", "教育の話ではない", "係の話ではない"]'::jsonb, '{"es": "Todo el discurso gira en torno a por qué conviene anotar los fallos: sin registro se repiten.", "en": "The whole talk is about why failures should be written down: without a record they repeat."}'::jsonb, '["うまくいった話は残る", "失敗は忘れられる", "同じ失敗をくり返す"]'::jsonb, null, '{"intro": "会社で女の人が話しています。", "turnos": [{"quien": "F", "texto": "うまくいったことは、放っておいても語り継がれます。問題は、うまくいかなかったことのほうです。誰も進んで書き残そうとしませんし、読み返すのも気が重い。ですが、記録がなければ、二年もすれば同じところで同じようにつまずきます。私たちが残すべきなのは成功例ではなく、どこで判断を誤ったかのほうなのです。"}], "pregunta": "この人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 5),
  ('n1-sokuji-0001', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'お忙しいところ恐れ入りますが、少々よろしいでしょうか。', null, '["ええ、かまいませんよ。", "ええ、恐れ入ります。", "いえ、少々です。"]'::jsonb, 0, '["謝る側の言葉を返している", "答えになっていない"]'::jsonb, '{"es": "Piden un momento con fórmula de disculpa: se concede con かまいません.", "en": "They''re asking for a moment with an apologetic formula: grant it with かまいません."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "お忙しいところ恐れ入りますが、少々よろしいでしょうか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 4),
  ('n1-sokuji-0002', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'この案、私が言うのもなんですが、少し無理があるのでは。', null, '["いえ、おっしゃるとおりです。", "はい、無理を言いました。", "では、私が言いましょう。"]'::jsonb, 0, '["無理を言ったのは相手ではない", "言う人の話ではない"]'::jsonb, '{"es": "Señalan con reservas que el plan cojea: se acepta la crítica con おっしゃるとおりです.", "en": "They hedge a criticism of the plan: you accept it with おっしゃるとおりです."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "この案、私が言うのもなんですが、少し無理があるのでは。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 5),
  ('n1-sokuji-0003', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'あの件、あれからどうなりましたっけ。', null, '["先週、無事に片づきましたよ。", "では、片づけておきます。", "まだ聞いていないんですか。"]'::jsonb, 0, '["これからの話にしている", "質問に答えていない"]'::jsonb, '{"es": "Preguntan por el desenlace de algo pasado: se responde contando cómo acabó.", "en": "They ask how something already under way turned out: you answer with the outcome."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "あの件、あれからどうなりましたっけ。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 4),
  ('n1-tanbun-0001', 'N1', 'tanbun', 'n1-tanbun-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者によると、助言が役に立たないと感じられる主な原因は何か。', null, '["専門家の知識が不足しているから", "問題の輪郭がどこまで見えているかが両者で異なるから", "助言する側の説明が長すぎるから", "求める側に専門知識がないから"]'::jsonb, 1, '["本文にない", "本文にない", "知識の差ではないと本文が否定している"]'::jsonb, '{"es": "El texto dice expresamente que no es una diferencia de conocimiento, sino de hasta dónde se ve el contorno del problema.", "en": "The text says explicitly it isn''t a knowledge gap but a difference in how far each side can see the shape of the problem."}'::jsonb, null, '{"texto": "専門家の助言が役に立たないと感じられるとき、その原因は助言の中身ではなく、前提の共有にあることが多い。助言する側は問題をすでに整理し終えた地点から話す。一方、助言を求める側は、まだ何が問題なのかを言葉にできていない段階にいる。両者の間にあるのは知識の差というより、問題の輪郭がどこまで見えているかの差なのである。したがって、有効な助言はしばしば答えの形をとらず、問いの立て直しという形をとる。", "notas": [{"termino": "輪郭", "glosa": "だいたいの形、外側の線"}]}'::jsonb, null, null, '["短文"]'::jsonb, 5),
  ('n1-tanbun-0002', 'N1', 'tanbun', 'n1-tanbun-g002', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は記録の意味をどこにあると考えているか。', null, '["後で読み返せること", "書く過程で出来事を整理し直すこと", "他人に伝わること", "正確さが保証されること"]'::jsonb, 1, '["読み返されるのは一部だと本文が否定している", "本文にない", "本文にない"]'::jsonb, '{"es": "El valor está en el propio acto de escribir, que obliga a reordenar lo ocurrido, aunque nadie vuelva a leerlo.", "en": "The value lies in the act of writing itself, which forces you to reorder what happened, even if nobody reads it again."}'::jsonb, null, '{"texto": "記録を残すことの価値は、後で読み返すことにあるとされがちだ。しかし実際に読み返される記録はごく一部にすぎない。それでも記録に意味があるのは、書く過程そのものが出来事を整理させるからである。何が起きたかを言葉にしようとした時点で、人はすでに一度その出来事を理解し直している。読まれない記録もまた、書かれた時点で確かに働いているのである。日記が続かないことを悔やむ人は多いが、悔やむ必要はない。続かなかった日々の分も、書いた日の理解は残っているからだ。", "notas": []}'::jsonb, null, null, '["短文"]'::jsonb, 5),
  ('n1-chuubun-0001', 'N1', 'chuubun', 'n1-chuubun-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は「問題は能力の総量ではなく、その配分なのである」と述べているが、どういうことか。', null, '["道具によって能力の合計が増えるということ", "道具は能力を奪うと同時に、注意の向け先を移すということ", "道具を使えば誰でも能力が高まるということ", "能力は測ることができないということ"]'::jsonb, 1, '["総量の話ではないと本文が否定している", "本文にない", "本文にない"]'::jsonb, '{"es": "El segundo párrafo lo explica: la herramienta quita una capacidad y a la vez desplaza hacia dónde va la atención.", "en": "The second paragraph explains it: the tool takes away one ability while shifting where attention goes."}'::jsonb, null, '{"texto": "新しい技術が現れるたびに、それが人間の能力を奪うのではないかという議論が起こる。計算機が普及したときには暗算の力が、地図の案内装置が広まったときには方向感覚が失われると言われた。実際、それらの能力は平均的には低下しているのかもしれない。\nしかし、失われたものだけを数えるのは公平ではない。道具は能力を奪うと同時に、注意を向ける先を移す。暗算に使っていた資源は別の思考に回され、地図を読むことに費やしていた注意は、目的地で何をするかに向けられる。問題は能力の総量ではなく、その配分なのである。\nもっとも、この配分が本人の選択によるものかどうかは別の話だ。道具が変えるのは可能性の形であって、それをどう使うかまでは決めてくれない。空いた資源が何にも向けられなければ、それは単に失われただけである。技術を批判するにせよ擁護するにせよ、この区別を曖昧にしたままでは議論は進まないだろう。\n私たちが問うべきなのは、その道具が何を肩代わりしてくれるかではない。肩代わりされた分の時間と注意を、自分が何に使うつもりでいるのかである。そこまで含めて考えたときにはじめて、道具は能力を奪うものではなく、選択を突きつけるものとして立ち現れてくる。", "notas": [{"termino": "配分", "glosa": "分け方、割りふり"}]}'::jsonb, null, null, '["中文"]'::jsonb, 5),
  ('n1-chuubun-0002', 'N1', 'chuubun', 'n1-chuubun-g001', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が最後の段落で言いたいことは何か。', null, '["技術は批判されるべきだ", "技術は擁護されるべきだ", "空いた資源をどう使うかは道具が決めてくれない", "道具は使わないほうがよい"]'::jsonb, 2, '["どちらの立場も取っていない", "どちらの立場も取っていない", "本文にない"]'::jsonb, '{"es": "Dice que la herramienta cambia la forma de lo posible pero no decide el uso: si el recurso liberado no va a nada, simplemente se perdió.", "en": "It says the tool changes what''s possible but doesn''t decide the use: if the freed resource goes nowhere, it''s simply lost."}'::jsonb, null, null, null, null, '["中文"]'::jsonb, 5),
  ('n1-tougou-0001', 'N1', 'tougou', 'n1-tougou-g001', 0, '次のAとBの文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '会議について、AとBが共通して認めていることは何か。', null, '["資料を事前に配ると会議の進み方が変わること", "会議は短いほどよいということ", "参加者全員が必ず資料を読むこと", "会議は判断の場にすべきでないこと"]'::jsonb, 0, '["Bは短さを目的にすることを批判している", "Bは読んでこない人がいると述べている", "Aは判断の場になると肯定している"]'::jsonb, '{"es": "Los dos parten de que repartir el material antes cambia cómo transcurre la reunión; discrepan en si ese cambio es bueno.", "en": "Both take it as given that handing out material beforehand changes how the meeting runs; they disagree on whether that change is good."}'::jsonb, null, '{"texto": "A\n会議の時間を短くするには、資料を事前に配ることだ。読めば分かることを読み上げる時間ほど無駄なものはない。参加者が目を通してきていれば、会議は判断の場になる。読んでこない人がいるという反論はあるだろうが、それは会議の問題ではなく参加者の問題である。\n\nB\n事前配布には限界がある。読んでくる人と読んでこない人がいれば、会議は前者の理解を前提に進み、後者は黙るしかない。結果として発言する人が固定され、決定の質はかえって下がる。短くすることだけを目的にすると、参加していない人を作り出してしまう。時間の長さより、誰が話せているかを見るべきだ。", "notas": []}'::jsonb, null, null, '["統合理解"]'::jsonb, 5),
  ('n1-tougou-0002', 'N1', 'tougou', 'n1-tougou-g001', 1, '次のAとBの文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '読んでこない参加者について、AとBの立場はどうちがうか。', null, '["Aは参加者側の問題だとし、Bは会議の質が下がる原因になるとしている", "AもBも参加者側の問題だとしている", "Aは会議の問題だとし、Bは参加者側の問題だとしている", "AもBも会議の運営の問題だとしている"]'::jsonb, 0, '["Bは会議の側の問題として扱っている", "AとBが逆", "Aは参加者の問題だと明言している"]'::jsonb, '{"es": "A lo despacha como problema del participante; B dice que produce gente que no participa y baja la calidad de la decisión.", "en": "A dismisses it as the participant''s problem; B says it manufactures non-participants and lowers decision quality."}'::jsonb, null, null, null, null, '["統合理解"]'::jsonb, 5),
  ('n1-kanji_yomi-0001', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '両者の主張は最後まで<u>隔たり</u>が大きかった。', null, '["へだたり", "かたより", "ひろがり", "つながり"]'::jsonb, 0, '["偏りは別語", "広がりは別語", "繋がりは別語"]'::jsonb, '{"es": "隔たり = へだたり, «distancia, brecha». 偏り (かたより) es «sesgo».", "en": "隔たり = へだたり, ''gap''. 偏り (かたより) is ''bias''."}'::jsonb, null, null, null, null, '["訓読み"]'::jsonb, 4),
  ('n1-kanji_yomi-0002', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '担当者の説明はきわめて<u>簡潔</u>だった。', null, '["かんけつ", "かんげつ", "けんけつ", "かんきつ"]'::jsonb, 0, '["濁点の誤り", "けんは別字", "促音の誤り"]'::jsonb, '{"es": "簡潔 = かんけつ, «conciso».", "en": "簡潔 = かんけつ, ''concise''."}'::jsonb, null, null, null, null, '["音読み"]'::jsonb, 3),
  ('n1-kanji_yomi-0003', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '彼は自らの過ちを<u>潔</u>く認めた。', null, '["いさぎよ", "きよ", "すがすが", "いさま"]'::jsonb, 0, '["清いの読み", "清々しいの読み", "存在しない読み"]'::jsonb, '{"es": "潔い = いさぎよい, «digno, sin excusas». 清い es きよい.", "en": "潔い = いさぎよい, ''clean, without excuses''. 清い is きよい."}'::jsonb, null, null, null, null, '["訓読み"]'::jsonb, 4),
  ('n1-bunmyaku-0001', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '長年の交渉の末、両国はようやく合意に（　）。', null, '["至った", "及んだ", "達した", "届いた"]'::jsonb, 2, '["至るは結果一般で合意には使いにくい", "及ぶは範囲", "届くは物理的"]'::jsonb, '{"es": "合意に達する es la colocación fija. 至る se usa con 結論 o 事態, no tanto con 合意.", "en": "合意に達する is the fixed collocation. 至る goes with 結論 or 事態 rather than 合意."}'::jsonb, null, null, null, null, '["コロケーション"]'::jsonb, 4),
  ('n1-bunmyaku-0002', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'その提案は現場の実情を（　）いないと批判された。', null, '["踏まえて", "据えて", "控えて", "擁して"]'::jsonb, 0, '["据えるは固定する", "控えるは差し控える", "擁するは抱える"]'::jsonb, '{"es": "実情を踏まえる = partir de la situación real. Es la colocación esperada.", "en": "実情を踏まえる = to be grounded in the actual situation. It''s the expected collocation."}'::jsonb, null, null, null, null, '["コロケーション"]'::jsonb, 4),
  ('n1-iikae-0001', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '彼の努力は<u>目覚ましい</u>成果をあげた。', null, '["非常にすぐれた", "わずかな", "予想どおりの", "一時的な"]'::jsonb, 0, '["逆の意味", "評価が入っていない", "時間の話ではない"]'::jsonb, '{"es": "目覚ましい = notable, asombroso. Marca un resultado muy por encima de lo normal.", "en": "目覚ましい = remarkable, striking. It marks a result well above the ordinary."}'::jsonb, null, null, null, null, '["形容詞"]'::jsonb, 4),
  ('n1-iikae-0002', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', 'この件については<u>おおむね</u>合意が得られている。', null, '["だいたい", "まったく", "わずかに", "ようやく"]'::jsonb, 0, '["完全という意味ではない", "少しではない", "時間の話ではない"]'::jsonb, '{"es": "おおむね = en líneas generales, la mayor parte. No es «del todo» ni «apenas».", "en": "おおむね = broadly, for the most part. Not ''entirely'' nor ''barely''."}'::jsonb, null, null, null, null, '["副詞"]'::jsonb, 3),
  ('n1-youhou-0001', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', 'のべ', null, '["この作業はのべ三時間で終わった。", "三日間でのべ千人が来場した。", "彼はのべ意見を述べた。", "のべ大きな声で呼んだ。"]'::jsonb, 1, '["実時間には使わない", "副詞ではない", "副詞ではない"]'::jsonb, '{"es": "延べ cuenta el total acumulado sumando días o personas, aunque se repitan. No es «en total de tiempo real».", "en": "延べ counts a cumulative total across days or people, repeats included. It isn''t ''in real elapsed time''."}'::jsonb, null, null, null, null, '["用法"]'::jsonb, 4),
  ('n1-youhou-0002', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', 'を踏まえて', null, '["前回の議論を踏まえて、案を作りなおした。", "会場を踏まえて、席を並べた。", "天気を踏まえて、雨が降った。", "彼を踏まえて、話を聞いた。"]'::jsonb, 0, '["場所には使わない", "結果を導く形になっていない", "人には使わない"]'::jsonb, '{"es": "〜を踏まえて toma algo previo (una discusión, unos datos) como base para lo siguiente.", "en": "〜を踏まえて takes something prior (a discussion, data) as the basis for what follows."}'::jsonb, null, null, null, null, '["用法"]'::jsonb, 4),
  ('n1-kanji_yomi-0004', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '事態の悪化を<u>阻</u>むために手を打った。', null, '["はば", "こば", "のぞ", "ふせ"]'::jsonb, 0, '["拒むの読み", "望むの読み", "防ぐの読み"]'::jsonb, '{"es": "阻む = はばむ, «impedir el paso». 拒む (こばむ) es «rechazar».", "en": "阻む = はばむ, ''to block''. 拒む (こばむ) is ''to refuse''."}'::jsonb, null, null, null, null, '["訓読み"]'::jsonb, 4),
  ('n1-kanji_yomi-0005', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '新制度の<u>是非</u>をめぐって議論が続いている。', null, '["ぜひ", "しひ", "ぜはい", "これひ"]'::jsonb, 0, '["是をしと読む誤り", "非をはいと読む誤り", "訓読みとの混同"]'::jsonb, '{"es": "是非 = ぜひ, aquí «lo acertado y lo desacertado», no el adverbio «por favor».", "en": "是非 = ぜひ, here ''the rights and wrongs'', not the adverb ''by all means''."}'::jsonb, null, null, null, null, '["音読み"]'::jsonb, 4),
  ('n1-kanji_yomi-0006', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '彼の功績は<u>著</u>しく評価が高い。', null, '["いちじる", "はなは", "あらわ", "めざま"]'::jsonb, 0, '["甚だしいの読み", "著すの別の読み", "目覚ましいの読み"]'::jsonb, '{"es": "著しい = いちじるしい. El mismo kanji leído あらわ- es 著す «escribir (una obra)».", "en": "著しい = いちじるしい. The same kanji read あらわ- gives 著す ''to author''."}'::jsonb, null, null, null, null, '["訓読み"]'::jsonb, 5),
  ('n1-bunmyaku-0003', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この分野の研究は、まだ（　）の段階にある。', null, '["模索", "詮索", "思索", "探検"]'::jsonb, 0, '["詮索は他人のことを調べる", "思索は静かに考える", "探検は場所"]'::jsonb, '{"es": "模索 = ir a tientas buscando el método. 詮索 es «fisgar» y 思索 «meditar».", "en": "模索 = groping for a method. 詮索 is ''prying'' and 思索 ''contemplation''."}'::jsonb, null, null, null, null, '["語彙"]'::jsonb, 5),
  ('n1-bunmyaku-0004', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '担当者の（　）な対応のおかげで、混乱せずにすんだ。', null, '["的確", "的中", "正確", "確実"]'::jsonb, 0, '["的中は予想が当たる", "正確は数値のずれ", "確実は間違いない"]'::jsonb, '{"es": "的確 = certero, ajustado a la situación. 正確 mide exactitud, no oportunidad.", "en": "的確 = apt, fitting the situation. 正確 measures accuracy, not aptness."}'::jsonb, null, null, null, null, '["語彙"]'::jsonb, 5),
  ('n1-bunmyaku-0005', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '証拠がそろわないうちは、結論を（　）べきだ。', null, '["控える", "抑える", "押さえる", "備える"]'::jsonb, 0, '["抑えるは感情や力", "押さえるは物理的", "備えるは準備"]'::jsonb, '{"es": "結論を控える = abstenerse de concluir. 抑える va con 感情 o costes.", "en": "結論を控える = to refrain from concluding. 抑える goes with emotions or costs."}'::jsonb, null, null, null, null, '["コロケーション"]'::jsonb, 5),
  ('n1-iikae-0003', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', 'その報告には<u>一抹</u>の不安が残る。', null, '["わずかな", "大きな", "確かな", "明らかな"]'::jsonb, 0, '["程度が逆", "確実さの話ではない", "明白さの話ではない"]'::jsonb, '{"es": "一抹の = una pizca de. Marca una cantidad mínima, no una grande.", "en": "一抹の = a trace of. It marks a minimal amount, not a large one."}'::jsonb, null, null, null, null, '["連体"]'::jsonb, 5),
  ('n1-iikae-0004', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '彼は<u>おのずから</u>答えにたどり着いた。', null, '["自然に", "急いで", "人に聞いて", "偶然に"]'::jsonb, 0, '["速さの話ではない", "他人は関わらない", "偶然とはちがう"]'::jsonb, '{"es": "おのずから = por sí solo, de forma natural. No es azar ni prisa.", "en": "おのずから = of itself, naturally. Not chance and not haste."}'::jsonb, null, null, null, null, '["副詞"]'::jsonb, 5),
  ('n1-iikae-0005', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '彼の話には<u>とりとめ</u>がない。', null, '["まとまりがない", "おもしろみがない", "根拠がない", "遠慮がない"]'::jsonb, 0, '["面白さの話ではない", "根拠の話ではない", "態度の話ではない"]'::jsonb, '{"es": "とりとめがない = deshilvanado, sin hilo. No es que sea falso ni aburrido.", "en": "とりとめがない = rambling, without a thread. Not false and not boring."}'::jsonb, null, null, null, null, '["慣用"]'::jsonb, 5),
  ('n1-youhou-0003', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', '目安', null, '["完成の目安は来月末です。", "彼を目安にして歩いた。", "目安を立てて席に着いた。", "この本は目安が高い。"]'::jsonb, 0, '["目印の誤用", "目標の誤用", "値段の誤用"]'::jsonb, '{"es": "目安 = referencia aproximada de cantidad o plazo. Para orientarse por un punto es 目印.", "en": "目安 = a rough guide for an amount or a date. To navigate by a point you''d use 目印."}'::jsonb, null, null, null, null, '["用法"]'::jsonb, 5),
  ('n1-youhou-0004', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', '打開', null, '["行きづまった状況を打開したい。", "古い建物を打開して新しくした。", "彼の意見を打開して認めた。", "窓を打開して風を入れた。"]'::jsonb, 0, '["取り壊すの誤用", "撤回するの誤用", "開けるの誤用"]'::jsonb, '{"es": "打開 = desbloquear una situación estancada. No se aplica a objetos ni a ventanas.", "en": "打開 = to break a deadlock. It doesn''t apply to objects or windows."}'::jsonb, null, null, null, null, '["用法"]'::jsonb, 5),
  ('n2-bunpou1-0001', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は仕事が忙しい（　）、会議には必ず出席する。', null, '["ものの", "ために", "おかげで", "ばかりに"]'::jsonb, 0, '["ためには理由", "おかげでは good cause", "ばかりにはbad cause"]'::jsonb, '{"es": "〜ものの = «aunque», concesivo. Los otros tres son de causa, y aquí no hay causa sino contraste.", "en": "〜ものの = ''although'', concessive. The other three mark cause, but this sentence contrasts rather than explains."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0002', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '一度引き受けた（　）、最後までやり遂げるつもりだ。', null, '["からには", "ところで", "とはいえ", "どころか"]'::jsonb, 0, '["ところでは逆接", "とはいえは逆接", "どころかは否定強調"]'::jsonb, '{"es": "〜からには = «ya que…, entonces por fuerza». Introduce la determinación que sigue.", "en": "〜からには = ''now that…, then of course''. It sets up the resolve that follows."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0003', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '今さら先生に言われた（　）、勉強する気にはなれない。', null, '["ところで", "からこそ", "ばかりに", "とともに"]'::jsonb, 0, '["からこそは肯定的理由", "ばかりにはbad cause", "とともには同時"]'::jsonb, '{"es": "〜たところで = «aunque me lo digan, da igual». Siempre lleva un resultado negativo o inútil.", "en": "〜たところで = ''even if they tell me, it won''t help''. It always leads to a futile or negative result."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0004', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼の実力（　）、優勝は当然の結果と言える。', null, '["からすれば", "にしては", "どころか", "において"]'::jsonb, 0, '["にしてはは期待外れ", "どころかは否定強調", "においては場面"]'::jsonb, '{"es": "〜からすれば = «a juzgar por». にしては diría lo contrario: que el resultado no cuadra con su nivel.", "en": "〜からすれば = ''judging from''. にしては would say the opposite: that the result doesn''t match his level."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0005', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '体調が悪いので、今回の出張は見送らざる（　）。', null, '["を得ない", "にすぎない", "ようがない", "ほかならない"]'::jsonb, 0, '["にすぎないは程度", "ようがないは手段の不在", "ほかならないは断定"]'::jsonb, '{"es": "〜ざるを得ない = «no queda más remedio que». Se une a la forma ない sin el ない: 見送らざるを得ない.", "en": "〜ざるを得ない = ''have no choice but to''. It attaches to the ない-stem: 見送らざるを得ない."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
